class ParallelClient:
    MAX_RETRIES = 3
    POLL_INTERVAL = 30
    MAX_POLL_TIME = 3600
    @staticmethod
    def _get_headers() -> Dict[str, str]:
        if not PARALLEL_API_KEY:
            return {}
        return {"x-api-key": PARALLEL_API_KEY, "Content-Type": "application/json"}
    @staticmethod
    def is_available() -> bool:
        return bool(PARALLEL_API_KEY)
    @classmethod
    def _request_with_retry(cls, method: str, url: str, **kwargs) -> Optional[requests.Response]:
        for attempt in range(cls.MAX_RETRIES):
            try:
                if method == 'POST':
                    response = requests.post(url, **kwargs)
                elif method == 'GET':
                    response = requests.get(url, **kwargs)
                else:
                    response = requests.request(method, url, **kwargs)
                if response.status_code == 429 or response.status_code >= 500:
                    wait_time = (2 ** attempt) * 2
                    logger.warning(f"Parallel API {response.status_code}, retrying in {wait_time}s")
                    time.sleep(wait_time)
                    continue
                return response
            except requests.Timeout:
                if attempt < cls.MAX_RETRIES - 1:
                    time.sleep((2 ** attempt) * 2)
                    continue
                return None
            except Exception as e:
                logger.error(f"Parallel request error: {str(e)}")
                if attempt < cls.MAX_RETRIES - 1:
                    time.sleep((2 ** attempt) * 2)
                    continue
                return None
        return None
    @classmethod
    def create_deep_research_task(cls, research_query: str, processor: str = "ultra", use_text_mode: bool = True) -> Optional[str]:
        if not cls.is_available():
            logger.warning("Parallel API key not available")
            return None
        try:
            payload: Dict[str, Any] = {"input": research_query, "processor": processor}
            if use_text_mode:
                payload["task_spec"] = {"output_schema": {"type": "text"}}
            response = cls._request_with_retry('POST', f"{PARALLEL_BASE_URL}/tasks/runs", headers=cls._get_headers(), json=payload, timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code in [200, 201, 202]:
                result = response.json()
                run_id = result.get('run_id')
                logger.info(f"Parallel Deep Research task created: {run_id} (processor: {processor}, status: {response.status_code})")
                return run_id
            elif response:
                logger.error(f"Parallel task creation failed: {response.status_code} - {response.text[:200]}")
                return None
        except Exception as e:
            logger.error(f"Parallel create task error: {str(e)}")
            return None
    @classmethod
    def get_task_status(cls, run_id: str) -> Optional[Dict[str, Any]]:
        if not cls.is_available():
            return None
        try:
            response = cls._request_with_retry('GET', f"{PARALLEL_BASE_URL}/tasks/runs/{run_id}", headers=cls._get_headers(), timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code == 200:
                return response.json()
            return None
        except Exception as e:
            logger.error(f"Parallel get status error: {str(e)}")
            return None
    @classmethod
    def get_task_result(cls, run_id: str) -> Optional[Dict[str, Any]]:
        if not cls.is_available():
            return None
        try:
            response = cls._request_with_retry('GET', f"{PARALLEL_BASE_URL}/tasks/runs/{run_id}/result", headers=cls._get_headers(), timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code == 200:
                return response.json()
            return None
        except Exception as e:
            logger.error(f"Parallel get result error: {str(e)}")
            return None
    @classmethod
    def poll_until_complete(cls, run_id: str, session_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
        if not cls.is_available():
            return None
        start_time = time.time()
        poll_count = 0
        while (time.time() - start_time) < cls.MAX_POLL_TIME:
            poll_count += 1
            status_data = cls.get_task_status(run_id)
            if not status_data:
                logger.error(f"Failed to get status for Parallel task {run_id}")
                return None
            status = status_data.get('status')
            logger.info(f"Parallel task {run_id} status: {status} (poll #{poll_count})")
            if session_id:
                elapsed_mins = int((time.time() - start_time) / 60)
                broadcast_sse_event(session_id, {'type': 'parallel_progress', 'status': status, 'elapsed_minutes': elapsed_mins, 'poll_count': poll_count})
            if status == "completed":
                result = cls.get_task_result(run_id)
                if result:
                    logger.info(f"Parallel Deep Research completed: {run_id}")
                    return result
                return None
            elif status == "failed":
                logger.error(f"Parallel task failed: {run_id}")
                return None
            time.sleep(cls.POLL_INTERVAL)
        logger.error(f"Parallel task {run_id} timed out after {cls.MAX_POLL_TIME}s")
        return None
    @classmethod
    def run_deep_research_sync(cls, research_query: str, processor: str = "ultra", session_id: Optional[str] = None) -> Optional[str]:
        if not cls.is_available():
            logger.warning("Parallel API not available - skipping")
            return None
        run_id = cls.create_deep_research_task(research_query, processor=processor, use_text_mode=True)
        if not run_id:
            logger.error("Failed to create Parallel research task")
            return None
        result = cls.poll_until_complete(run_id, session_id=session_id)
        if not result:
            logger.error(f"Parallel research failed or timed out: {run_id}")
            return None
        output = result.get('output', {})
        if isinstance(output, dict):
            content = output.get('content', '')
            basis = output.get('basis', [])
            if isinstance(content, str) and content:
                citations_count = len(basis) if isinstance(basis, list) else 0
                logger.info(f"Parallel research completed: {len(content)} chars, {citations_count} citations")
                return content
        logger.warning(f"Parallel result format unexpected: {type(output)}")
        return str(output) if output else None

