class SuperMemoryClient:
    MAX_RETRIES = 3
    @staticmethod
    def _get_headers() -> Dict[str, str]:
        if not SUPERMEMORY_API_KEY:
            return {}
        return {"Authorization": f"Bearer {SUPERMEMORY_API_KEY}", "Content-Type": "application/json"}
    @staticmethod
    def is_available() -> bool:
        return bool(SUPERMEMORY_API_KEY)
    @classmethod
    def _request_with_retry(cls, method: str, url: str, **kwargs) -> Optional[requests.Response]:
        for attempt in range(cls.MAX_RETRIES):
            try:
                if method == 'POST':
                    response = requests.post(url, **kwargs)
                elif method == 'DELETE':
                    response = requests.delete(url, **kwargs)
                elif method == 'GET':
                    response = requests.get(url, **kwargs)
                else:
                    response = requests.request(method, url, **kwargs)
                if response.status_code == 429 or response.status_code >= 500:
                    wait_time = (2 ** attempt) * 2
                    logger.warning(f"SuperMemory API {response.status_code}, retrying in {wait_time}s (attempt {attempt+1}/{cls.MAX_RETRIES})")
                    time.sleep(wait_time)
                    continue
                return response
            except requests.Timeout:
                wait_time = (2 ** attempt) * 2
                logger.warning(f"SuperMemory timeout, retrying in {wait_time}s (attempt {attempt+1}/{cls.MAX_RETRIES})")
                if attempt < cls.MAX_RETRIES - 1:
                    time.sleep(wait_time)
                    continue
                return None
            except Exception as e:
                logger.error(f"SuperMemory request error: {str(e)}")
                if attempt < cls.MAX_RETRIES - 1:
                    time.sleep((2 ** attempt) * 2)
                    continue
                return None
        return None
    @classmethod
    def add_memory(cls, content: str, metadata: Optional[Dict[str, Any]] = None, container_tags: Optional[List[str]] = None, custom_id: Optional[str] = None) -> Optional[Dict[str, Any]]:
        if not cls.is_available():
            logger.debug("SuperMemory not available - API key missing")
            return None
        try:
            payload: Dict[str, Any] = {"content": content}
            if metadata:
                payload["metadata"] = metadata
            if container_tags:
                payload["containerTags"] = container_tags
            if custom_id:
                payload["customId"] = custom_id
            response = cls._request_with_retry('POST', f"{SUPERMEMORY_BASE_URL}/v3/documents", headers=cls._get_headers(), json=payload, timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code in [200, 201]:
                result = response.json()
                logger.info(f"SuperMemory document added: {result.get('id', 'unknown')}")
                return result
            elif response:
                logger.warning(f"SuperMemory add failed: {response.status_code} - {response.text[:200]}")
                return None
        except Exception as e:
            logger.error(f"SuperMemory add error: {str(e)}")
            return None
    @classmethod
    def search_memories(cls, query: str, limit: int = 10, container_tags: Optional[List[str]] = None, rerank: bool = True) -> List[Dict[str, Any]]:
        if not cls.is_available():
            return []
        try:
            payload = {"q": query, "limit": min(limit, 50), "rerank": rerank}
            if container_tags:
                payload["containerTags"] = container_tags
            response = cls._request_with_retry('POST', f"{SUPERMEMORY_BASE_URL}/v3/search", headers=cls._get_headers(), json=payload, timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code == 200:
                result = response.json()
                memories = result.get('results', [])
                logger.info(f"SuperMemory search found {len(memories)} results for: {query[:50]}")
                return memories
            elif response:
                logger.warning(f"SuperMemory search failed: {response.status_code}")
                return []
        except Exception as e:
            logger.error(f"SuperMemory search error: {str(e)}")
            return []
    @classmethod
    def search_memories_v4(cls, query: str, limit: int = 10, user_id: Optional[str] = None, include_chunks: bool = True) -> List[Dict[str, Any]]:
        if not cls.is_available():
            return []
        try:
            payload = {"q": query, "limit": min(limit, 50), "includeChunks": include_chunks}
            if user_id:
                payload["filters"] = {"metadata.user_id": user_id}
            response = cls._request_with_retry('POST', f"{SUPERMEMORY_BASE_URL}/v4/search", headers=cls._get_headers(), json=payload, timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code == 200:
                result = response.json()
                return result.get('results', [])
            elif response:
                logger.warning(f"SuperMemory v4 search failed: {response.status_code}")
                return []
        except Exception as e:
            logger.error(f"SuperMemory v4 search error: {str(e)}")
            return []
    @classmethod
    def delete_memory(cls, document_id: str) -> bool:
        if not cls.is_available():
            return False
        try:
            response = cls._request_with_retry('DELETE', f"{SUPERMEMORY_BASE_URL}/v3/documents/{document_id}", headers=cls._get_headers(), timeout=DEFAULT_HTTP_TIMEOUT)
            if response and response.status_code in [200, 204]:
                logger.info(f"SuperMemory document deleted: {document_id}")
                return True
            elif response:
                logger.warning(f"SuperMemory delete failed: {response.status_code}")
                return False
        except Exception as e:
            logger.error(f"SuperMemory delete error: {str(e)}")
            return False
    @classmethod
    def add_chat_memory(cls, user_id: str, conversation_id: str, user_message: str, assistant_response: str) -> Optional[str]:
        content = f"""Felhasználó kérdése: {user_message}
AI válasz: {assistant_response}"""
        metadata = {"type": "chat", "user_id": user_id, "conversation_id": conversation_id, "timestamp": datetime.now().isoformat()}
        result = cls.add_memory(content=content, metadata=metadata, container_tags=["chat", f"user_{user_id}"], custom_id=f"chat_{conversation_id}_{uuid.uuid4().hex[:8]}")
        return result.get('id') if result else None
    @classmethod
    def add_research_memory(cls, user_id: str, session_id: str, goal: str, summary: str, sources_count: int) -> Optional[str]:
        content = f"""Kutatási téma: {goal}
Összefoglaló: {summary}
Feldolgozott források száma: {sources_count}"""
        metadata = {"type": "research", "user_id": user_id, "session_id": session_id, "sources_count": sources_count, "timestamp": datetime.now().isoformat()}
        result = cls.add_memory(content=content, metadata=metadata, container_tags=["research", f"user_{user_id}"], custom_id=f"research_{session_id}")
        return result.get('id') if result else None
    @classmethod
    def get_relevant_context(cls, user_id: str, query: str, max_results: int = 5) -> str:
        memories = cls.search_memories(query=query, limit=max_results, container_tags=[f"user_{user_id}"], rerank=True)
        if not memories:
            return ""
        context_parts = ["=== KORÁBBI RELEVÁNS INFORMÁCIÓK ==="]
        for i, mem in enumerate(memories[:max_results], 1):
            chunks = mem.get('chunks', [])
            if chunks:
                relevant_text = chunks[0].get('content', '')[:500]
            else:
                relevant_text = mem.get('content', '')[:500] if mem.get('content') else ''
            if relevant_text:
                context_parts.append(f"\n[{i}] {relevant_text}")
        context_parts.append("\n=== KONTEXTUS VÉGE ===\n")
        return "\n".join(context_parts)

