class GrokHeavyOrchestrator:
    def __init__(self, xai_api_key: str, gemini_api_key: str, anthropic_api_key: str):
        self.xai_api_key = xai_api_key
        self.gemini_api_key = gemini_api_key
        self.anthropic_api_key = anthropic_api_key
        self.num_grok_agents = 4
    def execute_heavy_reasoning(self, prompt: str, system_prompt: str = "", session_id: Optional[str] = None) -> str:
        agent_tasks = []
        for i in range(self.num_grok_agents):
            perspective = self._get_perspective(i)
            agent_tasks.append(lambda idx=i, persp=perspective: self._run_grok_agent(idx, prompt, system_prompt, persp, session_id))
        agent_tasks.append(lambda: self._run_gemini_agent(prompt, system_prompt))
        agent_tasks.append(lambda: self._run_opus_agent(prompt, system_prompt))
        valid_responses = []
        with ThreadPoolExecutor(max_workers=6) as executor:
            futures = [executor.submit(task) for task in agent_tasks]
            for future in as_completed(futures):
                try:
                    resp = future.result()
                    if isinstance(resp, GrokAgentResponse):
                        valid_responses.append(resp)
                except Exception as e:
                    logger.error(f"Agent execution error: {e}")
        if not valid_responses:
            return "Error: All agents failed"
        synthesized = self._synthesize_responses(prompt, valid_responses, session_id)
        return synthesized
    def _get_perspective(self, agent_id: int) -> str:
        perspectives = ["You are a critical skeptical analyst. Challenge assumptions and find weaknesses.", "You are an optimistic solution-oriented thinker. Focus on possibilities and opportunities.", "You are a data-driven analytical expert. Prioritize facts, numbers, and evidence.", "You are a creative unconventional thinker. Explore non-obvious angles and innovative approaches."]
        return perspectives[agent_id % len(perspectives)]
    def _run_grok_agent(self, agent_id: int, prompt: str, system_prompt: str, perspective: str, session_id: Optional[str] = None) -> GrokAgentResponse:
        combined_system = f"{system_prompt}\n\n{perspective}"
        try:
            headers = {"Authorization": f"Bearer {self.xai_api_key}", "Content-Type": "application/json"}
            payload = {"model": "grok-4-1-fast-non-reasoning", "messages": [{"role": "system", "content": combined_system}, {"role": "user", "content": prompt}], "temperature": 0.6 + (agent_id * 0.1), "max_tokens": 100000}
            start_time = time.time()
            response = requests.post("", headers=headers, json=payload, timeout=180)
            processing_time = time.time() - start_time
            if response.status_code != 200:
                return GrokAgentResponse(agent_id=f"grok_{agent_id}", model="grok-4", content=f"Error: {response.status_code}", confidence=0.0)
            result = response.json()
            content = result['choices'][0]['message']['content']
            tokens_used = result.get('usage', {}).get('total_tokens', 0)
            return GrokAgentResponse(agent_id=f"grok_{agent_id}", model="grok-4", content=content, confidence=0.75, temperature=0.6 + (agent_id * 0.1), tokens_used=tokens_used, processing_time=processing_time)
        except Exception as e:
            return GrokAgentResponse(agent_id=f"grok_{agent_id}", model="grok-4", content=f"Error: {str(e)}", confidence=0.0)
    def _run_gemini_agent(self, prompt: str, system_prompt: str) -> GrokAgentResponse:
        combined_prompt = f"{system_prompt}\n\n{prompt}"
        try:
            import google.generativeai as genai
            genai.configure(api_key=self.gemini_api_key)
            model = genai.GenerativeModel('gemini-2.0-flash-thinking-exp')
            start_time = time.time()
            response = model.generate_content(combined_prompt, generation_config=genai.types.GenerationConfig(temperature=0.7, max_output_tokens=8192))
            processing_time = time.time() - start_time
            return GrokAgentResponse(agent_id="gemini_0", model="gemini-3", content=response.text, confidence=0.8, processing_time=processing_time)
        except Exception as e:
            return GrokAgentResponse(agent_id="gemini_0", model="gemini-3", content=f"Error: {str(e)}", confidence=0.0)
    def _run_opus_agent(self, prompt: str, system_prompt: str) -> GrokAgentResponse:
        try:
            headers = {"x-api-key": self.anthropic_api_key, "Content-Type": "application/json", "anthropic-version": "2023-06-01"}
            payload = {"model": "claude-opus-4-20250514", "max_tokens": 8192, "temperature": 0.7, "system": system_prompt, "messages": [{"role": "user", "content": prompt}]}
            start_time = time.time()
            response = requests.post("", headers=headers, json=payload, timeout=180)
            processing_time = time.time() - start_time
            if response.status_code != 200:
                return GrokAgentResponse(agent_id="opus_0", model="claude-opus-4.5", content=f"Error: {response.status_code}", confidence=0.0)
            result = response.json()
            content = result['content'][0]['text']
            tokens_used = result.get('usage', {}).get('output_tokens', 0)
            return GrokAgentResponse(agent_id="opus_0", model="claude-opus-4.5", content=content, confidence=0.85, tokens_used=tokens_used, processing_time=processing_time)
        except Exception as e:
            return GrokAgentResponse(agent_id="opus_0", model="claude-opus-4.5", content=f"Error: {str(e)}", confidence=0.0)
    def _synthesize_responses(self, original_prompt: str, responses: List[GrokAgentResponse], session_id: Optional[str] = None) -> str:
        synthesis_context = f"Original Query: {original_prompt}\n\nAgent Responses:\n\n"
        for resp in responses:
            synthesis_context += f"Agent: {resp.agent_id} ({resp.model})\n"
            synthesis_context += f"Confidence: {resp.confidence}\n"
            synthesis_context += f"Response: {resp.content[:2000]}\n"
            synthesis_context += "-" * 80 + "\n\n"
        synthesis_prompt = f"""{synthesis_context}

Task: Synthesize these multi-agent responses into one unified, comprehensive answer.

Rules:
1. Identify consensus areas
2. Highlight unique insights from each agent
3. Resolve contradictions intelligently
4. Weight responses by confidence and quality
5. Produce a coherent final answer

Provide the synthesized response now."""
        try:
            headers = {"Authorization": f"Bearer {self.xai_api_key}", "Content-Type": "application/json"}
            payload = {"model": "grok-4-1-fast-non-reasoning", "messages": [{"role": "system", "content": "You are a meta-synthesis agent."}, {"role": "user", "content": synthesis_prompt}], "temperature": 0.5, "max_tokens": 100000}
            response = requests.post("", headers=headers, json=payload, timeout=180)
            if response.status_code == 200:
                result = response.json()
                return result['choices'][0]['message']['content']
        except Exception as e:
            logger.error(f"Synthesis error: {e}")
        high_conf = max(responses, key=lambda r: r.confidence)
        return high_conf.content

class TiffyTimeOrchestrator:
    def __init__(self):
        self.cerebras_api_key = os.environ.get("CEREBRAS_API_KEY")
        self.exa_api_key = os.environ.get("EXA_API_KEY")
        self.parallel_api_key = os.environ.get("PARALLEL_API_KEY")
        self.xai_api_key = os.environ.get("XAI_API_KEY")
        self.gemini_api_key = os.environ.get("GEMINI_API_KEY")
        self.anthropic_api_key = os.environ.get("ANTHROPIC_API_KEY")
        self.grok_heavy = GrokHeavyOrchestrator(xai_api_key=self.xai_api_key, gemini_api_key=self.gemini_api_key, anthropic_api_key=self.anthropic_api_key)
        self.max_output_tokens = 65000
        self.exa_result_limit = 100
    def execute_mission(self, user_query: str, session_id: str) -> ResearchState:
        task_id = hashlib.md5(f"{user_query}{time.time()}".encode()).hexdigest()[:16]
        state = ResearchState(task_id=task_id, query=user_query)
        try:
            self._planning_phase(state, session_id)
            self._execution_phase(state, session_id)
            self._synthesis_phase(state, session_id)
            state.status = "completed"
        except Exception as e:
            state.status = "failed"
            self._log_thought(state, f"Mission failed: {str(e)}")
            raise
        return state
    def _planning_phase(self, state: ResearchState, session_id: str):
        state.status = "planning"
        self._log_thought(state, "Planning with Grok Heavy multi-agent system")
        broadcast_sse_event(session_id, {'type': 'grok_heavy_planning_started', 'message': 'Grok Heavy 6-agent planning...'})
        planning_prompt = f"""Analyze this research query and create a structured plan.
Query: {state.query}

Output a JSON array of tasks. Each task must have:
- topic: specific research topic
- mode: either FAST_MODE or DEEP_MODE
- rationale: why this mode

FAST_MODE: Quick reconnaissance with Cerebras + Exa
DEEP_MODE: Deep investigation with Parallel Ultra8x

Return ONLY valid JSON array."""
        plan_text = self.grok_heavy.execute_heavy_reasoning(planning_prompt, "You are a master research strategist.", session_id)
        try:
            start = plan_text.find("[")
            end = plan_text.rfind("]") + 1
            if start != -1 and end > start:
                json_str = plan_text[start:end]
                plan_data = json.loads(json_str)
            else:
                plan_data = []
        except Exception as e:
            logger.error(f"Plan parsing error: {e}")
            plan_data = []
        if not plan_data:
            plan_data = [{"topic": state.query, "mode": "FAST_MODE", "rationale": "overview"}, {"topic": f"Deep analysis: {state.query}", "mode": "DEEP_MODE", "rationale": "depth"}]
        for idx, task_def in enumerate(plan_data):
            task = ResearchTaskItem(task_id=f"{state.task_id}_T{idx}", topic=task_def.get("topic", "Unknown"), mode=task_def.get("mode", "FAST_MODE"))
            state.plan.append(task)
        self._log_thought(state, f"Plan created: {len(state.plan)} tasks")
        broadcast_sse_event(session_id, {'type': 'grok_heavy_planning_complete', 'tasks_count': len(state.plan)})
    def _execution_phase(self, state: ResearchState, session_id: str):
        state.status = "executing"
        self._log_thought(state, "Executing research tasks in parallel")
        broadcast_sse_event(session_id, {'type': 'tiffytime_execution_started', 'tasks': len(state.plan)})
        def execute_task_wrapper(task: ResearchTaskItem) -> bool:
            try:
                if task.mode == "FAST_MODE":
                    self._execute_fast_mode(state, task, session_id)
                else:
                    self._execute_deep_mode(state, task, session_id)
                return True
            except Exception as e:
                logger.error(f"Task execution error: {e}")
                task.status = "failed"
                task.error = str(e)
                return False
        with ThreadPoolExecutor(max_workers=3) as executor:
            futures = {executor.submit(execute_task_wrapper, task): task for task in state.plan}
            for future in as_completed(futures):
                task = futures[future]
                try:
                    success = future.result()
                    if success:
                        task.status = "completed"
                except Exception as e:
                    logger.error(f"Task {task.task_id} failed: {e}")
                    task.status = "failed"
                    task.error = str(e)
    def _execute_fast_mode(self, state: ResearchState, task: ResearchTaskItem, session_id: str):
        task.status = "running"
        self._log_thought(state, f"FAST MODE: {task.topic} (Cerebras GPT-OSS + Exa Fast)")
        broadcast_sse_event(session_id, {'type': 'fast_mode_started', 'task_id': task.task_id, 'topic': task.topic})
        exa_results = self._call_exa_search(task.topic, num_results=self.exa_result_limit)
        sources = []
        excerpts = []
        for result in exa_results[:50]:
            url = result.get('url', '')
            if url:
                sources.append(url)
            text = result.get('text', '')
            if text:
                excerpts.append(f"Source: {url}\n{text[:1500]}")
        task.sources = sources
        combined_text = "\n\n".join(excerpts)
        processing_prompt = f"""Extract and synthesize key information from {len(excerpts)} web sources about: {task.topic}

Sources:
{combined_text}

Provide structured summary with:
1. Key facts and statistics
2. Main themes
3. Notable sources
4. Contradictions or gaps

Be concise but comprehensive."""
        response = self._call_cerebras_chat([{"role": "system", "content": "You are a rapid information synthesizer."}, {"role": "user", "content": processing_prompt}], max_tokens=8000, temperature=0.6)
        task.result = response
        state.context_memory.append({"task_id": task.task_id, "topic": task.topic, "mode": "FAST_MODE", "content": task.result, "sources": task.sources[:20], "timestamp": datetime.now().isoformat()})
        self._log_thought(state, f"FAST MODE completed: {task.topic}")
        broadcast_sse_event(session_id, {'type': 'fast_mode_completed', 'task_id': task.task_id})
    def _execute_deep_mode(self, state: ResearchState, task: ResearchTaskItem, session_id: str):
        task.status = "running"
        self._log_thought(state, f"DEEP MODE: {task.topic} (Parallel Ultra8x)")
        broadcast_sse_event(session_id, {'type': 'deep_mode_started', 'task_id': task.task_id, 'topic': task.topic})
        parallel_result = ParallelClient.run_deep_research_sync(task.topic, processor="ultra8x", session_id=session_id)
        if not parallel_result:
            parallel_result = "Parallel research unavailable or failed"
        parallel_summary = parallel_result[:10000]
        validation_prompt = f"""Review this deep research result for: {task.topic}

Research Output:
{parallel_summary}

Identify:
1. Strength of evidence
2. Information gaps
3. Contradictions
4. Follow-up questions

Provide critical analysis."""
        grok_validation = self.grok_heavy.execute_heavy_reasoning(validation_prompt, "You are a critical research validator.", session_id)
        combined_result = f"""PARALLEL ULTRA8X RESEARCH:
{parallel_summary}

GROK HEAVY VALIDATION:
{grok_validation}"""
        task.result = combined_result
        task.sources = ["Parallel Ultra8x", "Grok Heavy Multi-Agent"]
        state.context_memory.append({"task_id": task.task_id, "topic": task.topic, "mode": "DEEP_MODE", "content": task.result, "sources": task.sources, "timestamp": datetime.now().isoformat()})
        self._log_thought(state, f"DEEP MODE completed: {task.topic}")
        broadcast_sse_event(session_id, {'type': 'deep_mode_completed', 'task_id': task.task_id})
    def _synthesis_phase(self, state: ResearchState, session_id: str):
        state.status = "synthesizing"
        self._log_thought(state, "Designing report structure with Grok Heavy")
        broadcast_sse_event(session_id, {'type': 'synthesis_started', 'message': 'Grok Heavy report synthesis...'})
        all_findings = "\n\n".join([f"TOPIC: {mem['topic']}\nMODE: {mem['mode']}\nCONTENT: {mem['content'][:2000]}" for mem in state.context_memory])
        structure_prompt = f"""Design comprehensive report structure for this research.

Query: {state.query}

Research Summary:
{all_findings[:8000]}

Output JSON array of sections:
- title: section heading
- focus: what to cover
- priority: high/medium/low

Return ONLY valid JSON array."""
        structure_text = self.grok_heavy.execute_heavy_reasoning(structure_prompt, "You are a report architect.", session_id)
        try:
            start = structure_text.find("[")
            end = structure_text.rfind("]") + 1
            if start != -1 and end > start:
                json_str = structure_text[start:end]
                structure = json.loads(json_str)
            else:
                structure = []
        except Exception as e:
            logger.error(f"Structure parsing error: {e}")
            structure = []
        if not structure:
            structure = [{"title": "Executive Summary", "focus": "Overview", "priority": "high"}, {"title": "Detailed Findings", "focus": "Main content", "priority": "high"}, {"title": "Analysis and Insights", "focus": "Deep analysis", "priority": "high"}, {"title": "Recommendations", "focus": "Actions", "priority": "medium"}]
        self._log_thought(state, f"Report structure: {len(structure)} sections")
        for section_def in structure:
            section_title = section_def.get("title", "Section")
            section_focus = section_def.get("focus", "")
            relevant_context = self._retrieve_relevant_context(state, f"{section_title} {section_focus}")
            section_text = self._generate_report_section(state, section_title, section_focus, relevant_context, session_id)
            state.report_sections[section_title] = section_text
        self._log_thought(state, "Report synthesis completed")
        broadcast_sse_event(session_id, {'type': 'synthesis_completed', 'sections': len(state.report_sections)})
    def _retrieve_relevant_context(self, state: ResearchState, query: str) -> str:
        relevant = []
        query_lower = query.lower()
        for mem in state.context_memory:
            topic_lower = mem['topic'].lower()
            content_lower = mem['content'].lower()
            if any(word in topic_lower or word in content_lower for word in query_lower.split()):
                relevant.append(mem)
        if not relevant:
            relevant = state.context_memory
        context_text = "\n\n".join([f"Topic: {mem['topic']}\nMode: {mem['mode']}\nContent: {mem['content'][:3000]}" for mem in relevant[:5]])
        return context_text
    def _generate_report_section(self, state: ResearchState, section_title: str, section_focus: str, context: str, session_id: str) -> str:
        self._log_thought(state, f"Writing section: {section_title} (Cerebras GPT-OSS)")
        broadcast_sse_event(session_id, {'type': 'report_section_writing', 'section': section_title})
        writing_prompt = f"""Write comprehensive section for research report.

Section: {section_title}
Focus: {section_focus}

Context and Research Findings:
{context[:15000]}

Requirements:
- Professional academic tone
- Detailed and thorough
- Include specific facts and data
- Reference key sources
- Target 3000-8000 words

Write complete section now."""
        response = self._call_cerebras_chat([{"role": "system", "content": "You are an expert research report writer."}, {"role": "user", "content": writing_prompt}], max_tokens=self.max_output_tokens, temperature=0.7)
        return response
    def _log_thought(self, state: ResearchState, message: str):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        entry = f"[{timestamp}] {message}"
        state.thought_log.append(entry)
    def get_full_report(self, state: ResearchState) -> str:
        if not state.report_sections:
            return "No report generated yet."
        report_parts = [f"TIFFYTIME PRO RESEARCH REPORT", f"Query: {state.query}", f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}", f"Task ID: {state.task_id}", "=" * 80, ""]
        for title, content in state.report_sections.items():
            report_parts.append(f"\n{'=' * 80}")
            report_parts.append(f"{title}")
            report_parts.append(f"{'=' * 80}\n")
            report_parts.append(content)
            report_parts.append("")
        report_parts.append("\n" + "=" * 80)
        report_parts.append("RESEARCH METADATA")
        report_parts.append("=" * 80)
        report_parts.append(f"Tasks executed: {len(state.plan)}")
        report_parts.append(f"FAST MODE tasks: {sum(1 for t in state.plan if t.mode == 'FAST_MODE')}")
        report_parts.append(f"DEEP MODE tasks: {sum(1 for t in state.plan if t.mode == 'DEEP_MODE')}")
        report_parts.append(f"Total context items: {len(state.context_memory)}")
        report_parts.append(f"Thought log entries: {len(state.thought_log)}")
        return "\n".join(report_parts)
    def save_report(self, state: ResearchState, filename: Optional[str] = None) -> str:
