def call_tiffy_api(system_prompt: str, user_message: str, max_tokens: int = 2000000, temperature: float = 0.7, include_reasoning: bool = False, session_id: Optional[str] = None, max_retries: int = 3, enable_tools: bool = False, attached_images: Optional[List[Dict]] = None, enable_live_search: bool = True, from_date: Optional[str] = None, to_date: Optional[str] = None) -> Dict[str, Any]:
    api_key = get_grok4_api_key()
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    model_name = "grok-4-1-fast-reasoning" if include_reasoning else "grok-4-1-fast-non-reasoning"
    payload: Dict[str, Any] = {"model": model_name, "messages": [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_message}], "max_tokens": max_tokens, "temperature": max(0.0, min(2.0, temperature)), "stream": include_reasoning}
    if enable_live_search:
        search_params: Dict[str, Any] = {"mode": "auto", "sources": [{"type": "web"}, {"type": "x"}, {"type": "news"}], "return_citations": True, "max_search_results": 30}
        if from_date:
            search_params["from_date"] = from_date
        if to_date:
            search_params["to_date"] = to_date
        payload["search_parameters"] = search_params
    if include_reasoning:
        payload["reasoning"] = {"effort": "high"}
    if enable_tools:
        payload["tools"] = [{"type": "function", "function": {"name": "web_search", "description": "Search the web for information", "parameters": {"query": {"type": "string"}}}}, {"type": "function", "function": {"name": "twitter_search", "description": "Search X (Twitter) for real-time information", "parameters": {"query": {"type": "string"}}}}, {"type": "function", "function": {"name": "execute_python_code", "description": "Execute Python code for calculations or data manipulation", "parameters": {"code": {"type": "string"}}}}, {"type": "function", "function": {"name": "analyze_data", "description": "Perform data analysis and generate visualizations", "parameters": {"data": {"type": "string"}, "analysis_type": {"type": "string"}}}}, {"type": "function", "function": {"name": "understand_image", "description": "Analyze and understand image content", "parameters": {"image_url": {"type": "string"}}}}]
        payload["tool_choice"] = "auto"
    if attached_images:
        payload["images"] = attached_images
    last_error = None
    for attempt in range(max_retries):
        start_time = time.time()
        try:
            if include_reasoning and session_id:
                response = requests.post("", headers=headers, json=payload, timeout=180, stream=True)
                if response.status_code == 429:
                    wait_time = (2 ** attempt) * 2
                    logger.warning(f"Tiffy API rate limited (429), retrying in {wait_time}s (attempt {attempt+1}/{max_retries})")
                    time.sleep(wait_time)
                    continue
                if response.status_code != 200:
                    logger.error(f"Tiffy API error: {response.status_code}")
                    raise Exception(f"Tiffy API returned {response.status_code}")
                content = ""
                reasoning_content = ""
                tool_calls = []
                citations = []
                tokens_used = 0
                for line in response.iter_lines():
                    if line:
                        line_text = line.decode('utf-8')
                        if line_text.startswith('data: '):
                            json_str = line_text[6:]
                            if json_str.strip() == '[DONE]':
                                break
                            try:
                                chunk = json.loads(json_str)
                                delta = chunk.get('choices', [{}])[0].get('delta', {})
                                if 'reasoning_content' in delta and delta['reasoning_content']:
                                    reasoning_content += delta['reasoning_content']
                                    if session_id:
                                        broadcast_sse_event(session_id, {'type': 'thinking', 'content': delta['reasoning_content']})
                                        with _state_lock:
                                            session = RESEARCH_SESSIONS.get(session_id)
                                            if session:
                                                session.current_thinking = reasoning_content
                                if 'tool_calls' in delta:
                                    tool_calls.extend(delta['tool_calls'])
                                if 'citations' in delta and delta['citations']:
                                    citations.extend(delta['citations'])
                                if 'content' in delta and delta['content']:
                                    content += delta['content']
                                if 'usage' in chunk:
                                    tokens_used = chunk['usage'].get('total_tokens', 0)
                            except json.JSONDecodeError:
                                continue
                processing_time = time.time() - start_time
                return {'content': content, 'reasoning': reasoning_content, 'tool_calls': tool_calls, 'citations': citations, 'tokens_used': tokens_used, 'processing_time': processing_time}
            else:
                non_stream_payload = payload.copy()
                non_stream_payload["stream"] = False
                if "reasoning" in non_stream_payload:
                    del non_stream_payload["reasoning"]
                response = requests.post("", headers=headers, json=non_stream_payload, timeout=180)
                if response.status_code == 429:
                    wait_time = (2 ** attempt) * 2
                    logger.warning(f"Tiffy API rate limited (429), retrying in {wait_time}s (attempt {attempt+1}/{max_retries})")
                    time.sleep(wait_time)
                    continue
                processing_time = time.time() - start_time
                if response.status_code != 200:
                    logger.error(f"Tiffy API error: {response.status_code}")
                    raise Exception(f"Tiffy API returned {response.status_code}")
                result = response.json()
                content = result['choices'][0]['message']['content']
                tokens_used = result.get('usage', {}).get('total_tokens', 0)
                tool_calls = result['choices'][0].get('message', {}).get('tool_calls', [])
                citations = result['choices'][0].get('message', {}).get('citations', [])
                return {'content': content, 'tokens_used': tokens_used, 'processing_time': processing_time, 'tool_calls': tool_calls, 'citations': citations}
        except requests.Timeout:
            logger.error("Tiffy API timeout")
            last_error = Exception("API timeout")
            if attempt < max_retries - 1:
                time.sleep((2 ** attempt) * 2)
                continue
        except Exception as e:
            logger.error(f"Tiffy API error: {str(e)}")
            last_error = e
            if "429" in str(e) and attempt < max_retries - 1:
                time.sleep((2 ** attempt) * 2)
                continue
            raise
    if last_error:
        raise last_error
    raise Exception("Max retries exceeded")

def call_grok4_api(system_prompt: str, user_message: str, max_tokens: int = 2000000, temperature: float = 0.7) -> Dict[str, Any]:
    return call_tiffy_api(system_prompt, user_message, max_tokens, temperature, include_reasoning=False)

def call_cerebras_chat(messages: List[Dict[str, str]], max_tokens: int = 65000, temperature: float = 1.0, top_p: float = 0.95, max_retries: int = 3) -> str:
    for attempt in range(max_retries):
        try:
            client = get_cerebras_client()
            response = client.chat.completions.create(model="gpt-oss-120b", max_tokens=max_tokens, messages=cast(Any, messages), temperature=max(0.0, min(2.0, temperature)), top_p=max(0.0, min(1.0, top_p)))
            resp_obj = cast(Any, response)
            content = resp_obj.choices[0].message.content if resp_obj.choices else ""
            return content if isinstance(content, str) else str(content or "")
        except Exception as e:
            error_str = str(e).lower()
            is_retryable = any(x in error_str for x in ['429', 'rate limit', 'timeout', '500', '502', '503', '504'])
            if is_retryable and attempt < max_retries - 1:
                wait_time = (2 ** attempt) * 2
                logger.warning(f"Cerebras chat error, retrying in {wait_time}s (attempt {attempt+1}/{max_retries}): {str(e)[:100]}")
                time.sleep(wait_time)
                continue
            logger.error(f"Cerebras chat error: {str(e)}")
            raise
    return ""

_state_lock = threading.RLock()
_cleanup_lock = threading.Lock()
