def validate_goal(goal: str) -> str:
    if not goal or not isinstance(goal, str):
        raise ValueError("Kutatási cél szükséges")
    goal = goal.strip()
    if len(goal) < 5:
        raise ValueError("Kutatási cél túl rövid (min 5 karakter)")
    if len(goal) > 5000:
        raise ValueError("Kutatási cél túl hosszú (max 5000 karakter)")
    return goal

def validate_message(message: str) -> str:
    if not message or not isinstance(message, str):
        raise ValueError("Üzenet szükséges")
    message = message.strip()
    if len(message) < 1:
        raise ValueError("Üzenet nem lehet üres")
    if len(message) > 10000:
        raise ValueError("Üzenet túl hosszú")
    return message

